  "12. Cambios a esta política": { en: "12. Changes to this policy", fr: "12. Modifications de cette politique", pt: "12. Alterações desta política" },
  "Si modificamos esta política te notificaremos dentro de la app antes de que entre en vigor.": { en: "If we change this policy we'll notify you in the app before it takes effect.", fr: "Si nous modifions cette politique, nous vous en informerons dans l'app avant son entrée en vigueur.", pt: "Se alterarmos esta política, notificaremos no app antes de entrar em vigor." },
  "Selecciona un lugar para reservar": { en: "Select a place to book", fr: "Sélectionnez un lieu à réserver", pt: "Selecione um lugar para reservar" },
  "Partner no encontrado": { en: "Partner not found", fr: "Partenaire introuvable", pt: "Parceiro não encontrado" },
  "Te conectamos con AMO Life por WhatsApp para gestionar tu reserva.": { en: "We'll connect you with AMO Life on WhatsApp to manage your booking.", fr: "Nous vous mettons en relation avec AMO Life sur WhatsApp pour gérer votre réservation.", pt: "Conectamos você com o AMO Life pelo WhatsApp para gerenciar sua reserva." },
  "Te conectamos con el partner por WhatsApp. Confirma tu reserva directamente.": { en: "We'll connect you with the partner on WhatsApp. Confirm your booking directly.", fr: "Nous vous mettons en relation avec le partenaire sur WhatsApp. Confirmez directement.", pt: "Conectamos você com o parceiro pelo WhatsApp. Confirme sua reserva diretamente." },
  "No se pudo abrir WhatsApp. Verifica que tengas la app instalada.": { en: "Couldn't open WhatsApp. Make sure the app is installed.", fr: "Impossible d'ouvrir WhatsApp. Vérifiez que l'app est installée.", pt: "Não foi possível abrir o WhatsApp. Verifique se o app está instalado." },
  "o ingresa otra fecha (AAAA-MM-DD):": { en: "or enter another date (YYYY-MM-DD):", fr: "ou entrez une autre date (AAAA-MM-JJ) :", pt: "ou insira outra data (AAAA-MM-DD):" },
  "Hora": { en: "Time", fr: "Heure", pt: "Hora" },
  "o ingresa otra hora (HH:MM):": { en: "or enter another time (HH:MM):", fr: "ou entrez une autre heure (HH:MM) :", pt: "ou insira outro horário (HH:MM):" },
