  "Cumpleaños, alergias, mesa especial…": { en: "Birthday, allergies, special table…", fr: "Anniversaire, allergies, table spéciale…", pt: "Aniversário, alergias, mesa especial…" },
  "¿Cómo funciona?": { en: "How does it work?", fr: "Comment ça marche ?", pt: "Como funciona?" },
  "1) Enviamos tu solicitud al partner.": { en: "1) We send your request to the partner.", fr: "1) Nous envoyons votre demande au partenaire.", pt: "1) Enviamos sua solicitação ao parceiro." },
  "2) El partner confirma o rechaza en su panel.": { en: "2) The partner confirms or declines in their panel.", fr: "2) Le partenaire confirme ou refuse dans son panneau.", pt: "2) O parceiro confirma ou recusa no painel dele." },
  "3) Si confirma, recibes su link de pago directamente en la app.": { en: "3) If confirmed, you get their payment link directly in the app.", fr: "3) S'il confirme, vous recevez son lien de paiement directement dans l'app.", pt: "3) Se confirmar, você recebe o link de pagamento direto no app." },
  "Cancelación gratuita hasta 2h antes de la reserva.": { en: "Free cancellation up to 2h before the booking.", fr: "Annulation gratuite jusqu'à 2h avant la réservation.", pt: "Cancelamento gratuito até 2h antes da reserva." },
