  // ── Seasonal stamp descriptions ──
  "Un sello ganado viendo el sol caer sobre la muralla — desde 45 min antes hasta 20 min después del ocaso.": { en: "A stamp earned watching the sun drop over the city wall — from 45 min before to 20 min after sunset.", fr: "Un tampon gagné en regardant le soleil se coucher sur les remparts — de 45 min avant à 20 min après le coucher.", pt: "Um selo ganho vendo o sol cair sobre a muralha — de 45 min antes até 20 min depois do pôr do sol." },
  "Castillo San Felipe de Barajas, dentro del horario de visita (8am–6pm).": { en: "Castillo San Felipe de Barajas, within visiting hours (8am–6pm).", fr: "Castillo San Felipe de Barajas, pendant les heures de visite (8h–18h).", pt: "Castillo San Felipe de Barajas, dentro do horário de visita (8h–18h)." },
  "Entrada gratis el último domingo del mes (excepto enero y diciembre) — un sello que solo aparece ese día.": { en: "Free entry the last Sunday of the month (except January and December) — a stamp that only appears that day.", fr: "Entrée gratuite le dernier dimanche du mois (sauf janvier et décembre) — un tampon qui n'apparaît que ce jour-là.", pt: "Entrada grátis no último domingo do mês (exceto janeiro e dezembro) — um selo que só aparece nesse dia." },
  "Palacio de la Inquisición, dentro del horario (lun–sáb 9–6, dom 10–4).": { en: "Palacio de la Inquisición, within hours (Mon–Sat 9–6, Sun 10–4).", fr: "Palacio de la Inquisición, pendant les heures (lun–sam 9–18, dim 10–16).", pt: "Palácio da Inquisição, dentro do horário (seg–sáb 9–18, dom 10–16)." },
  "Donde Fidel, en la Plaza de los Coches — salsa y champeta desde las 4pm.": { en: "Donde Fidel, in Plaza de los Coches — salsa and champeta from 4pm.", fr: "Donde Fidel, sur la Plaza de los Coches — salsa et champeta dès 16h.", pt: "Donde Fidel, na Plaza de los Coches — salsa e champeta a partir das 16h." },
  "Un sello de la noche cartagenera — jueves a sábado, cuando la ciudad se enciende.": { en: "A stamp of Cartagena nightlife — Thursday to Saturday, when the city lights up.", fr: "Un tampon de la nuit de Carthagène — du jeudi au samedi, quand la ville s'anime.", pt: "Um selo da noite cartageneira — de quinta a sábado, quando a cidade se acende." },
  "La ciudad en su día más tranquilo — un sello para quien la camina un lunes.": { en: "The city on its quietest day — a stamp for those who walk it on a Monday.", fr: "La ville en son jour le plus calme — un tampon pour ceux qui la parcourent un lundi.", pt: "A cidade no seu dia mais tranquilo — um selo para quem a caminha numa segunda." },
  "El pulso de la ciudad al amanecer — antes de las 9am, cuando el mercado despierta.": { en: "The pulse of the city at dawn — before 9am, when the market wakes up.", fr: "Le pouls de la ville à l'aube — avant 9h, quand le marché se réveille.", pt: "O pulso da cidade ao amanhecer — antes das 9h, quando o mercado desperta." },
  "Diciembre a abril — cielo despejado, brisa fuerte. Estuviste en temporada seca.": { en: "December to April — clear skies, strong breeze. You were here in the dry season.", fr: "De décembre à avril — ciel dégagé, brise forte. Vous étiez en saison sèche.", pt: "De dezembro a abril — céu limpo, brisa forte. Você esteve na temporada seca." },
  "Mayo a noviembre — aguaceros cortos, ciudad más verde y menos llena.": { en: "May to November — short downpours, a greener and less crowded city.", fr: "De mai à novembre — averses courtes, ville plus verte et moins bondée.", pt: "De maio a novembro — aguaceiros curtos, cidade mais verde e menos cheia." },
  "Octubre, el mes más lluvioso — un sello para quien camina bajo el aguacero.": { en: "October, the rainiest month — a stamp for those who walk through the downpour.", fr: "Octobre, le mois le plus pluvieux — un tampon pour ceux qui marchent sous l'averse.", pt: "Outubro, o mês mais chuvoso — um selo para quem caminha sob o aguaceiro." },
  "Independencia de Cartagena (11 de noviembre) — semana pico ~6–15 nov. Un sello anual fijo.": { en: "Independence of Cartagena (November 11) — peak week ~Nov 6–15. A fixed annual stamp.", fr: "Indépendance de Carthagène (11 novembre) — semaine forte ~6–15 nov. Un tampon annuel fixe.", pt: "Independência de Cartagena (11 de novembro) — semana pico ~6–15 nov. Um selo anual fixo." },
  "Peregrinación al Cerro de la Popa (2 de febrero) — novenario desde finales de enero.": { en: "Pilgrimage to Cerro de la Popa (February 2) — novena from late January.", fr: "Pèlerinage au Cerro de la Popa (2 février) — neuvaine dès fin janvier.", pt: "Peregrinação ao Cerro de la Popa (2 de fevereiro) — novena desde o fim de janeiro." },
  "Del 16 al 24 de diciembre — novenas, velitas y ciudad en fiesta.": { en: "From December 16 to 24 — novenas, candles and a city in festivity.", fr: "Du 16 au 24 décembre — neuvaines, bougies et ville en fête.", pt: "De 16 a 24 de dezembro — novenas, velinhas e cidade em festa." },
  "Un trago al caer la tarde en un rooftop — ventana genérica de atardecer (horarios varían, confirma en el lugar).": { en: "A drink at dusk on a rooftop — a generic sunset window (hours vary, confirm on site).", fr: "Un verre au crépuscule sur un rooftop — fenêtre générique de coucher de soleil (horaires variables, confirmez sur place).", pt: "Um drink ao entardecer num rooftop — janela genérica de pôr do sol (horários variam, confirme no local)." },
  "Festival Internacional de Música (~principios de enero). Edición 2026 finalizada; fecha 2027 sin confirmar.": { en: "International Music Festival (~early January). 2026 edition finished; 2027 date unconfirmed.", fr: "Festival international de musique (~début janvier). Édition 2026 terminée ; date 2027 non confirmée.", pt: "Festival Internacional de Música (~início de janeiro). Edição 2026 encerrada; data 2027 sem confirmar." },
  "Hay Festival (~finales de enero). Edición 2026 finalizada; fecha 2027 sin confirmar.": { en: "Hay Festival (~late January). 2026 edition finished; 2027 date unconfirmed.", fr: "Hay Festival (~fin janvier). Édition 2026 terminée ; date 2027 non confirmée.", pt: "Hay Festival (~fim de janeiro). Edição 2026 encerrada; data 2027 sem confirmar." },
  "Festival Internacional de Cine (~marzo/abril). Edición 2026 finalizada; fecha 2027 sin confirmar.": { en: "International Film Festival (~March/April). 2026 edition finished; 2027 date unconfirmed.", fr: "Festival international du film (~mars/avril). Édition 2026 terminée ; date 2027 non confirmée.", pt: "Festival Internacional de Cinema (~março/abril). Edição 2026 encerrada; data 2027 sem confirmar." },
  "Semana Santa y Festival de Música Sacra — se mueve con la Pascua. Edición 2026 finalizada; fecha 2027 sin confirmar.": { en: "Holy Week and Sacred Music Festival — moves with Easter. 2026 edition finished; 2027 date unconfirmed.", fr: "Semaine sainte et Festival de musique sacrée — varie avec Pâques. Édition 2026 terminée ; date 2027 non confirmée.", pt: "Semana Santa e Festival de Música Sacra — muda com a Páscoa. Edição 2026 encerrada; data 2027 sem confirmar." },
  "Un sello para los días de llegada de crucero — requiere el calendario en vivo de la terminal.": { en: "A stamp for cruise arrival days — requires the terminal's live schedule.", fr: "Un tampon pour les jours d'arrivée de croisière — nécessite le calendrier en direct du terminal.", pt: "Um selo para os dias de chegada de cruzeiro — requer o calendário ao vivo do terminal." },

