  'Ingresa el NIT o registro del negocio': { en: 'Enter the business tax ID (NIT) or registration', fr: 'Saisissez le NIT ou l’immatriculation de l’établissement', pt: 'Digite o NIT ou registro do negócio' },
  'Enviado a revisión': { en: 'Sent for review', fr: 'Envoyé pour examen', pt: 'Enviado para análise' },
  'Tu negocio pasó a revisión del equipo. No aparece en el catálogo hasta ser aprobado.': { en: 'Your business is now under team review. It won’t appear in the catalog until approved.', fr: 'Votre établissement est en cours d’examen par l’équipe. Il n’apparaîtra pas dans le catalogue avant approbation.', pt: 'Seu negócio está em análise pela equipe. Ele não aparece no catálogo até ser aprovado.' },
